INSERT INTO articles (title, slug, destination, start_date, end_date, content, short_description, cover_url, folder_id, status) VALUES ('Maroc Mai 2014 – Fès', 'maroc-mai-2014-fes', 'Maroc', '2014-05-01', '2014-05-14', '27/04/2014 20:05 : décolage de Nantes. Dans 3 heures, nous serons à l''''aéroport de Fès, Maroc, où nous attendra notre voiture de location grand luxe (dacia logan avec clim et GiPièS).', '27/04/2014 20:05 : décolage de Nantes. Dans 3 heures, nous serons à l''''''''aéroport de Fès, Maroc, où nous attendra notre voiture de location grand luxe (dacia logan avec clim et GiPièS).', NULL, (SELECT id FROM folders WHERE slug = 'maroc'), 'published');
INSERT INTO articles (title, slug, destination, start_date, end_date, content, short_description, cover_url, folder_id, status) VALUES ('Maroc Avril 2015', 'maroc-avril-2015', 'Maroc', '2015-04-01', '2015-04-14', 'Cette année,  décollage de Tours. Nous atterrissons à l''''aéroport de Marrakech, Maroc, où nous attendra notre loueur de Dacia et notre GPS. Nous leur avons demandé une voiture avec le plein d''''essence, mais ça n''''est pas dans leur habitude. C''''est simplement plus rassurant pour nous. Une fois les papiers signés et la caution enregistrée, direction Imouzzer, près d''''Agadir, dans la vallée du paradis où nous passerons 3 nuits. Voici le trajet prévu cette année :', 'Cette année,  décollage de Tours. Nous atterrissons à l''''''''aéroport de Marrakech, Maroc, où nous attendra notre loueur de Dacia et notre GPS. Nous leur avons demandé une voiture avec le plein d''''''''ess', NULL, (SELECT id FROM folders WHERE slug = 'maroc'), 'published');
